// Mole/gram/particle conversion tool.
// Converts among grams, moles, and molecule counts given a molar mass
// from an inline mini-table.

export const AVOGADRO = 6.02214076e23;

/** Inline mini-table of molar masses (g/mol). */
const MOLAR_MASSES: Record<string, number> = {
  H2O: 18.015,
  CO2: 44.009,
  NaCl: 58.44,
};

export type Substance = keyof typeof MOLAR_MASSES;

export function molarMassOf(substance: Substance): number {
  const m = MOLAR_MASSES[substance];
  if (m === undefined) {
    throw new Error(`Unknown substance: ${substance}. Known: ${Object.keys(MOLAR_MASSES).join(", ")}`);
  }
  return m;
}

export function gramsToMoles(grams: number, substance: Substance): number {
  return grams / molarMassOf(substance);
}

export function molesToGrams(moles: number, substance: Substance): number {
  return moles * molarMassOf(substance);
}

export function molesToMolecules(moles: number): number {
  return moles * AVOGADRO;
}

export function moleculesToMoles(molecules: number): number {
  return molecules / AVOGADRO;
}

export function gramsToMolecules(grams: number, substance: Substance): number {
  return molesToMolecules(gramsToMoles(grams, substance));
}

export function moleculesToGrams(molecules: number, substance: Substance): number {
  return molesToGrams(moleculesToMoles(molecules), substance);
}

