import { describe, it, expect } from "vitest";
import {
  AVOGADRO,
  gramsToMoles,
  molesToGrams,
  molesToMolecules,
  moleculesToMoles,
  gramsToMolecules,
  moleculesToGrams,
} from "./amounts";

describe("amounts conversions", () => {
  it("18.015 g H2O = 1.0000 mol within 1e-4", () => {
    expect(Math.abs(gramsToMoles(18.015, "H2O") - 1)).toBeLessThanOrEqual(1e-4);
  });

  it("18.015 g H2O = 6.0221e23 molecules within 0.001e23", () => {
    const molecules = gramsToMolecules(18.015, "H2O");
    expect(Math.abs(molecules - AVOGADRO)).toBeLessThanOrEqual(0.001e23);
  });

  it("0.5 mol CO2 = 22.0045 g within 0.001", () => {
    expect(Math.abs(molesToGrams(0.5, "CO2") - 22.0045)).toBeLessThanOrEqual(0.001);
  });

  it("1.2044e24 molecules NaCl = 2.0000 mol within 1e-4", () => {
    expect(Math.abs(moleculesToMoles(1.2044e24) - 2)).toBeLessThanOrEqual(1e-4);
  });

  it("1.2044e24 molecules NaCl = 116.88 g within 0.01", () => {
    expect(Math.abs(moleculesToGrams(1.2044e24, "NaCl") - 116.88)).toBeLessThanOrEqual(0.01);
  });
});

describe("round-trip property (grams -> moles -> molecules -> grams)", () => {
  // Seeded PRNG (mulberry32)
  function mulberry32(seed: number): () => number {
    return () => {
      seed |= 0;
      seed = (seed + 0x6d2b79f5) | 0;
      let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  const substances = ["H2O", "CO2", "NaCl"] as const;

  it("is the identity within 1e-9 relative error for 100 random cases", () => {
    const rand = mulberry32(42);
    for (let i = 0; i < 100; i++) {
      const substance = substances[Math.floor(rand() * substances.length)];
      // Random mass in [0.001, 1000] g (log-uniform-ish to span magnitudes)
      const grams = 0.001 + rand() * rand() * 999.999;

      const moles = gramsToMoles(grams, substance);
      const molecules = molesToMolecules(moles);
      const backToGrams = moleculesToGrams(molecules, substance);

      const relErr = Math.abs((backToGrams - grams) / grams);
      expect(relErr, `case ${i}: ${grams} g ${substance} -> ${backToGrams} g`).toBeLessThanOrEqual(1e-9);
    }
  });
});

